import AppKit
import SwiftUI

/// The DeepSeek whale mark shown to the left of the notch while a turn runs.
///
/// Loaded as a bitmap rather than drawn: the mark is DeepSeek's logo, and a
/// hand-approximated path would just read as a different whale. The bytes are
/// generated by `scripts/make-whale-mark.py` and **embedded in the source** (see
/// `WhaleMarkData`), not shipped as a SwiftPM resource bundle.
///
/// That distinction is not cosmetic. The first implementation used
/// `Bundle.module`, which traps at first render with `unable to find bundle named
/// DynamicIslandBridge_DynamicIslandBridge` as soon as the sidecar `.bundle` is
/// not next to the binary — and `scripts/build-helper.sh` copies only the
/// executable, so every packaged copy would have died the moment progress
/// arrived. Embedding keeps the helper a single self-contained file.
enum WhaleMarkAsset {
    static func image() -> NSImage? {
        // The literal is wrapped across lines for reviewable diffs, hence the
        // tolerance for embedded newlines.
        guard let data = Data(base64Encoded: WhaleMarkData.pngBase64, options: .ignoreUnknownCharacters) else {
            return nil
        }
        return NSImage(data: data)
    }
}

/// Compact-state leading content: the whale, in the notch's left wing.
///
/// Only the library's *notch* view draws compact leading content — `NotchlessView`
/// renders the expanded content alone — so this appears on notched screens while
/// a turn is running, and on no other path.
struct WhaleMark: View {
    /// The pill's digits are 11pt inside a roughly 20pt content box (the notch is
    /// 32pt tall and the library's safe-area insets take 4pt top + 8pt bottom), so
    /// the mark matches that budget rather than the notch's full height.
    private static let height: CGFloat = 13

    var body: some View {
        if let image = WhaleMarkAsset.image() {
            Image(nsImage: image)
                .resizable()
                .interpolation(.high)
                .scaledToFit()
                .frame(height: Self.height)
                // The library insets only compactLeading's *outer* (leading) edge,
                // so the gap facing the notch has to be supplied here — mirroring
                // what the pill does on the other side.
                .padding(.trailing, 8)
                .accessibilityHidden(true)
        }
    }
}
